/*
 * MSG-01 · Estilos de la pantalla de hilos (cabecera, acciones, paginación).
 *
 * La lista de filas y el estado vacío viven en ThreadList.module.css.
 * Todo color sale del vocabulario cerrado de tokens: ningún hex literal.
 */

.screen {
  width: 100%;
}

/* ── Cabecera de pantalla ─────────────────────────────────────────────── */

.pageHeader {
  margin-bottom: 16px;
}

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-text-secondary);
}

.pageTitle {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-input-text);
}

.pageSubtitle {
  margin: 0;
  max-width: 560px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

/* ── Estado E2EE de la sesión ─────────────────────────────────────────── */

.e2eeBar {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin: 0 0 14px;
  padding: 5px 10px;
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: var(--bw-radius);
  color: var(--bw-signal-green);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* ── Barra de acciones ────────────────────────────────────────────────── */

.actionsBar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.searchForm {
  position: relative;
  flex: 1;
  min-width: 220px;
  max-width: 300px;
  margin: 0;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  color: var(--bw-input-text);
  font-family: inherit;
  font-size: 13px;
  outline: none;
  transition: border-color 0.15s ease;
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.newContact {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
}

.btnPrimary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: var(--bw-radius);
  color: var(--bw-on-dark-hover);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: not-allowed;
  opacity: 0.6;
}

.scopeNote {
  font-size: 10px;
  line-height: 1.4;
  color: var(--bw-hint-steel);
  white-space: nowrap;
}

.pagInfo {
  margin-left: auto;
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

/* ── Estados de contenido ─────────────────────────────────────────────── */

.errorBanner {
  padding: 10px 12px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  color: var(--bw-sensitive-text);
  font-size: 13px;
  line-height: 1.5;
}

.loadingPane {
  padding: 36px 0;
  color: var(--bw-steel-mist);
  font-size: 14px;
  text-align: center;
}

/* ── Paginación ───────────────────────────────────────────────────────── */

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageNum,
.pageCtrl {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  color: var(--bw-ink-steel);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
  transition:
    border-color 0.12s ease,
    color 0.12s ease;
}

.pageNum:not(:disabled):hover,
.pageCtrl:not(:disabled):hover {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageNum:disabled,
.pageCtrl:disabled {
  color: var(--bw-hint-steel);
  background: var(--bw-divider-mist);
  border-color: var(--bw-line-steel);
  cursor: default;
}

.pageCurrent,
.pageCurrent:disabled {
  color: var(--bw-on-dark-hover);
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  cursor: default;
}

