import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';

import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import { ThreadList } from './ThreadList';

import styles from './Messages.module.css';

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es la pantalla completa: posee la búsqueda, la página actual y la llamada a
 * `fetchThreadPage(profile.orgId)`. `ThreadList` es solo presentacional.
 *
 * El botón "Nuevo contacto" abre DIR-01, que no está entre las pantallas del
 * MVP (Plan §9): se pinta deshabilitado y con el motivo visible, igual que el
 * botón de subida de INV-01 (F-023). No hay passphrase ni recuperación en el
 * MVP (CLAUDE.md §4), así que tampoco se ofrece "Introducir frase de
 * seguridad"; las claves viven en memoria de sesión y el contenido se
 * descifra localmente.
 */

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * Firma pública del componente (F-118). El shell la cableó desde `App.tsx`
   * después de escribirse esta tarea, y sin declararla el repo no compila.
   * MSG-02 no existía cuando se escribió esta pantalla: abrir un hilo no
   * lleva a ningún sitio, así que la prop se recibe y se ignora.
   */
  onOpenThread?: (threadId: string) => void;
}

/** PostgREST rechaza con un objeto plano `{ code, message }`, no con un `Error`
 *  siempre: hay que extraer `code`/`message` antes de caer a `String(e)`
 *  (F-128, F-020). */
function describeError(cause: unknown): string {
  if (cause && typeof cause === 'object') {
    const { code, message } = cause as { code?: unknown; message?: unknown };
    const pieces = [
      typeof code === 'string' ? code : '',
      typeof message === 'string' ? message : '',
    ].filter(Boolean);
    if (pieces.length > 0) return pieces.join(' · ');
  }
  if (cause instanceof Error) return cause.message;
  return String(cause);
}

/**
 * `ThreadList` exige un `onOpen`. MSG-02 no está en el alcance (ver F-118),
 * así que el stub no navega a ningún sitio: solo cumple el contrato de tipos.
 */
function openInboxStub(_threadId: string): void {
  /* La apertura del hilo se implementa en MSG-02, fuera del MVP. */
}

export function Messages({ profile, now }: MessagesProps) {
  const [query, setQuery] = useState('');
  const [appliedSearch, setAppliedSearch] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[] | null>(null);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let stale = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search: appliedSearch, page })
      .then((result) => {
        if (stale) return;
        setThreads(result.threads);
        setTotal(result.total);
      })
      .catch((cause: unknown) => {
        if (stale) return;
        setThreads(null);
        setError(describeError(cause));
      })
      .finally(() => {
        if (!stale) setLoading(false);
      });

    return () => {
      stale = true;
    };
  }, [appliedSearch, page, profile.orgId]);

  const totalPages = pageCount(total);
  const pageNumbers = Array.from({ length: totalPages }, (_, index) => index + 1);

  function handleSearchSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const next = query.trim();
    if (next === appliedSearch) return;
    setAppliedSearch(next);
    setPage(1);
  }

  function goToPage(nextPage: number) {
    if (nextPage < 1 || nextPage > totalPages || nextPage === page) return;
    setPage(nextPage);
  }

  return (
    <div className={styles.screen}>
      <header className={styles.pageHeader}>
        <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
        <h1 className={styles.pageTitle}>Hilos</h1>
        <p className={styles.pageSubtitle}>
          Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo
          a extremo.
        </p>
      </header>

      <p className={styles.e2eeBar}>
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · contenido descifrado localmente
      </p>

      <div className={styles.actionsBar}>
        <form className={styles.searchForm} role="search" onSubmit={handleSearchSubmit}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="search"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={query}
            onChange={(event) => setQuery(event.target.value)}
          />
        </form>

        <div className={styles.newContact}>
          <button type="button" className={styles.btnPrimary} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          {/* El motivo visible de que el botón esté apagado: abre DIR-01, que
              no se entrega en el MVP. Es el mismo patrón que `directorio-scope`
              y el mismo literal que el estado vacío de ThreadList (F-144). */}
          <span data-testid="directorio-scope" className={styles.scopeNote}>
            El Directorio queda fuera del MVP.
          </span>
        </div>

        <span data-testid="pag-info" className={styles.pagInfo}>
          {`${total.toLocaleString('es-ES')} hilos · Página ${page.toLocaleString(
            'es-ES',
          )} de ${totalPages.toLocaleString('es-ES')}`}
        </span>
      </div>

      {error !== null ? (
        <div role="alert" className={styles.errorBanner}>
          No se pudieron cargar los hilos. {error}
        </div>
      ) : loading && threads === null ? (
        <div className={styles.loadingPane} role="status">
          Cargando hilos…
        </div>
      ) : (
        <>
          <ThreadList threads={threads ?? []} now={now} onOpen={openInboxStub} />
          {total > 0 && (
            <nav className={styles.pagination} aria-label="Paginación de hilos">
              <button
                type="button"
                className={styles.pageCtrl}
                aria-label="Página anterior"
                disabled={page === 1}
                onClick={() => goToPage(page - 1)}
              >
                ‹
              </button>
              {pageNumbers.map((number) => (
                <button
                  key={number}
                  type="button"
                  className={`${styles.pageNum}${
                    number === page ? ` ${styles.pageCurrent}` : ''
                  }`}
                  disabled={number === page}
                  onClick={() => goToPage(number)}
                >
                  {number}
                </button>
              ))}
              <button
                type="button"
                className={styles.pageCtrl}
                aria-label="Página siguiente"
                disabled={page === totalPages}
                onClick={() => goToPage(page + 1)}
              >
                ›
              </button>
            </nav>
          )}
        </>
      )}
    </div>
  );
}

