/*
 * MSG-01 · Lista de hilos — estilos de las filas y del estado vacío.
 *
 * Todo color sale del vocabulario cerrado de tokens: ningún hex literal.
 * El fondo de tarjeta "blanco" del HTML aprobado no tiene token propio en el
 * sistema (F-003); se usa --bw-surface-mist, el neutro de superficie clara
 * más cercano.
 */

/* ── Tarjeta de lista ─────────────────────────────────────────────────── */

.threadList {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  overflow: hidden;
}

.threadItem {
  border-bottom: 1px solid var(--bw-divider-mist);
  transition: background 0.1s ease;
}

.threadItem:last-child {
  border-bottom: none;
}

.threadItem:hover {
  background: var(--bw-row-hover-tint);
}

/* ── Botón de apertura de fila ────────────────────────────────────────── */

.threadButton {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  column-gap: 10px;
  row-gap: 5px;
  align-items: center;
  width: 100%;
  padding: 14px 18px;
  background: none;
  border: 0;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.threadButton:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.threadTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.threadOrg {
  min-width: 0;
  overflow: hidden;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-input-text);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.countryBadge {
  flex: 0 0 auto;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  line-height: 1.5;
  padding: 1px 6px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.threadTime {
  justify-self: end;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.threadBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  grid-column: 1 / -1;
  min-width: 0;
}

.threadPreview {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  font-size: 12px;
  color: var(--bw-steel-mist);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Badge de estado del hilo ─────────────────────────────────────────── */

.stateBadge {
  flex-shrink: 0;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  line-height: 1.6;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border: 1px solid transparent;
  border-radius: 2px;
  white-space: nowrap;
}

.toneNeutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border-color: var(--bw-badge-neutral-border);
}

.toneInfo {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border-color: var(--bw-chip-active-border);
}

.toneWarn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border-color: var(--bw-badge-warning-border);
}

.toneSuccess {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border-color: var(--bw-badge-success-border);
}

.toneClosed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-hint-steel);
  border-color: var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* ── Estado vacío ─────────────────────────────────────────────────────── */

.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 48px 24px;
  text-align: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
}

.emptyMessage {
  margin: 0;
  max-width: 420px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-ink-steel);
}

.emptyButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 36px;
  margin-top: 4px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: var(--bw-radius);
  color: var(--bw-on-dark-hover);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  cursor: not-allowed;
  opacity: 0.6;
}

.emptyReason {
  margin: 0;
  font-size: 11px;
  color: var(--bw-hint-steel);
}

