import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Recibe las filas ya cargadas y en el orden que manda el servidor
 * (`last_item_at` descendente). No consulta la base de datos ni pagina: eso
 * lo posee `Messages.tsx`.
 *
 * Cada fila es un `<li>` con un `<button>` dentro (F-131): el elemento de
 * lista conserva su rol implícito `listitem` y es el botón quien lleva el
 * nombre accesible del hilo. Nunca se pone un `role` sobre el `<li>`.
 *
 * El estado vacío vive en un contenedor aparte, fuera de cualquier `<ul>`
 * (F-141): con cero hilos no debe quedar ningún `listitem` en el documento.
 */

const EMPTY_MESSAGE =
  'Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.';
const EMPTY_BUTTON = 'Ir al Directorio';
const EMPTY_REASON = 'El Directorio queda fuera del MVP.';

/**
 * Clase CSS por tono de estado.
 *
 * El tipo es `string | undefined` a propósito (F-143): con
 * `noUncheckedIndexedAccess` cualquier propiedad de `styles` puede no existir.
 * El hueco se resuelve en el único punto de consumo con `?? ''`.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.toneNeutral,
  info: styles.toneInfo,
  warn: styles.toneWarn,
  success: styles.toneSuccess,
  closed: styles.toneClosed,
};

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /** Avisa con el ID del hilo, no con el objeto. */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyMessage}>{EMPTY_MESSAGE}</p>
        {/* DIR-01 no está en el alcance del MVP (Plan §9), igual que el botón
            "Nuevo contacto" de Messages: el botón existe pero está apagado y el
            motivo se ve al lado, como el botón de subida de INV-01 (F-023). */}
        <button type="button" className={styles.emptyButton} disabled>
          {EMPTY_BUTTON}
        </button>
        <p className={styles.emptyReason}>{EMPTY_REASON}</p>
      </div>
    );
  }

  return (
    <ul className={styles.threadList}>
      {threads.map((thread) => {
        const toneClass = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          <li key={thread.id} className={styles.threadItem}>
            <button
              type="button"
              className={styles.threadButton}
              aria-label={thread.counterpartyName}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.threadTop}>
                <span className={styles.threadOrg}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry !== '' && (
                  <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
                )}
              </span>
              <time className={styles.threadTime} dateTime={thread.lastItemAt}>
                {relativeTime(thread.lastItemAt, now)}
              </time>
              <span className={styles.threadBottom}>
                <span className={styles.threadPreview}>{previewLabel(thread.lastItem)}</span>
                <span className={`${styles.stateBadge} ${toneClass}`}>{thread.state}</span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
